package org.apache.commons.cli;

import java.io.*;
import java.io.PrintWriter;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collection;
import java.util.Collections;
import java.util.Comparator;
import java.util.Iterator;
import java.util.List;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class HelpFormatter_findWrapPos_TriageGen2Test {

    private HelpFormatter formatter;

    @Before
    public void setUp() {
        formatter = new HelpFormatter();
    }

    @Test
    public void testFindWrapPos_WithNewlineBeforeWidth() {
        String text = "This is a test\nwith a newline";
        assertEquals(6, formatter.findWrapPos(text, 10, 0));
    }

    @Test
    public void testFindWrapPos_WithTabBeforeWidth() {
        String text = "This\tis\ta\ttest";
        assertEquals(5, formatter.findWrapPos(text, 10, 0));
    }

    @Test
    public void testFindWrapPos_WithWhitespaceBeforeWidth() {
        String text = "This is a test";
        assertEquals(5, formatter.findWrapPos(text, 10, 0));
    }

    @Test
    public void testFindWrapPos_WithoutWhitespaceBeforeWidth() {
        String text = "Thisisatest";
        assertEquals(10, formatter.findWrapPos(text, 10, 0));
    }

    @Test
    public void testFindWrapPos_StartAtEndOfString() {
        String text = "This is a test";
        assertEquals(-1, formatter.findWrapPos(text, 10, text.length()));
    }

    @Test
    public void testFindWrapPos_StartPosGreaterThanWidth() {
        String text = "This is a test";
        assertEquals(5, formatter.findWrapPos(text, 3, 5));
    }

    @Test
    public void testFindWrapPos_ExactMatchWidth() {
        String text = "ExactWidth";
        assertEquals(9, formatter.findWrapPos(text, 9, 0));
    }

    @Test
    public void testFindWrapPos_NoWhitespaceAtAll() {
        String text = "Nonspaced";
        assertEquals(9, formatter.findWrapPos(text, 9, 0));
    }

    @Test
    public void testFindWrapPos_EmptyString() {
        String text = "";
        assertEquals(-1, formatter.findWrapPos(text, 10, 0));
    }

    @Test
    public void testFindWrapPos_StartPosAtEnd() {
        String text = "EdgeCase";
        assertEquals(-1, formatter.findWrapPos(text, 10, 7));
    }

    @Test
    public void testFindWrapPos_StartPosInMiddle() {
        String text = "MidStart";
        assertEquals(3, formatter.findWrapPos(text, 3, 3));
    }

    @Test
    public void testFindWrapPos_WhitespaceAtEnd() {
        String text = "Whitespace ";
        assertEquals(11, formatter.findWrapPos(text, 10, 0));
    }

    @Test
    public void testFindWrapPos_NewlineAtEnd() {
        String text = "Newline\n";
        assertEquals(7, formatter.findWrapPos(text, 10, 0));
    }

    @Test
    public void testFindWrapPos_MultipleWhitespace() {
        String text = "Multiple    spaces";
        assertEquals(8, formatter.findWrapPos(text, 10, 0));
    }

    @Test
    public void testFindWrapPos_MixedCharacters() {
        String text = "Mixed\n\tcharacters";
        assertEquals(5, formatter.findWrapPos(text, 10, 0));
    }
}
